    "imagem": "https://netdeal.com.br/api/images/proxy?quality=100&width=1200&src=https://www.netdeal.com.br/api/images/producao.spayce.com.br/1787324188257_dsc_8735.jpg",
    "resumo": "Fórum independente em Vitória reúne credores e avalia estrutura coletiva para negociações e eventual recuperação de valores aplicados.",
    "fonteNome": "A Gazeta - Capa",
